require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/PayrollRepository.php';Auth::requireLogin();if(!Auth::can('payroll.manage')&&!PayrollRepository::canPublish()){http_response_code(403);exit('دسترسی غیرمجاز است.');}$pageTitle='دوره‌های حقوق و دستمزد';$adminExtraStylesheets=['/assets/css/workforce.css'];
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'save')==='save'&&!PayrollRepository::canManage()){flash('برای تغییر دوره حقوقی دسترسی ندارید.','danger');redirect('/admin/payroll-periods.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/payroll-periods.php');}try{$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);if($action==='publish'){if(!PayrollRepository::canPublish())throw new InvalidArgumentException('مجوز انتشار فیش‌ها را ندارید.');$period=PayrollRepository::assertPeriodEditable($id);if(!in_array($period['status'],['imported','published'],true))throw new InvalidArgumentException('دوره باید ابتدا ایمپورت و بررسی شود.');$pdo=Database::connection();$pdo->beginTransaction();try{Database::execute("UPDATE payroll_slips SET status='published',published_at=COALESCE(published_at,NOW()),updated_at=NOW() WHERE period_id=? AND status IN ('draft','ready','published')",[$id]);Database::execute("UPDATE payroll_periods SET status='published',updated_at=NOW() WHERE id=?",[$id]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}Auth::log((int)Auth::user()['id'],'payroll_period_published','payroll_periods',$id);flash('فیش‌های دوره منتشر شدند.');}elseif($action==='lock'){if(!PayrollRepository::canPublish())throw new InvalidArgumentException('مجوز قفل دوره را ندارید.');$period=PayrollRepository::assertPeriodEditable($id);if($period['status']!=='published')throw new InvalidArgumentException('فقط دوره منتشرشده قابل قفل است.');Database::execute("UPDATE payroll_periods SET status='locked',updated_at=NOW() WHERE id=?",[$id]);Auth::log((int)Auth::user()['id'],'payroll_period_locked','payroll_periods',$id);flash('دوره قفل شد.');}elseif($action==='unlock'){if(!Auth::isSuperAdmin())throw new InvalidArgumentException('بازکردن قفل فقط برای سوپرادمین مجاز است.');Database::execute("UPDATE payroll_periods SET status='published',updated_at=NOW() WHERE id=? AND status='locked'",[$id]);Auth::log((int)Auth::user()['id'],'payroll_period_unlocked','payroll_periods',$id);flash('قفل دوره باز شد.');}elseif($action==='cancel'){if(!PayrollRepository::canPublish())throw new InvalidArgumentException('مجوز لغو دوره را ندارید.');PayrollRepository::assertPeriodEditable($id);Database::execute("UPDATE payroll_periods SET status='cancelled',updated_at=NOW() WHERE id=?",[$id]);Database::execute("UPDATE payroll_slips SET status='cancelled',updated_at=NOW() WHERE period_id=?",[$id]);Auth::log((int)Auth::user()['id'],'payroll_period_cancelled','payroll_periods',$id);flash('دوره لغو شد؛ هیچ داده‌ای حذف نشد.');}else{$title=trim((string)($_POST['title']??''));$key=trim((string)($_POST['period_key']??''));$year=(int)($_POST['year']??0);$month=(int)($_POST['month']??0);if($title===''||$key===''||$year<1300||$month<1||$month>12)throw new InvalidArgumentException('عنوان، کلید، سال و ماه معتبر الزامی است.');if($id)PayrollRepository::assertPeriodEditable($id);if(Database::fetch('SELECT id FROM payroll_periods WHERE period_key=? AND id<>?',[$key,$id]))throw new InvalidArgumentException('کلید دوره تکراری است.');$startRaw=trim((string)($_POST['start_date']??''));$endRaw=trim((string)($_POST['end_date']??''));$start=$startRaw===''?null:app_date_to_iso($startRaw);$end=$endRaw===''?null:app_date_to_iso($endRaw);if(($startRaw!==''&&!$start)||($endRaw!==''&&!$end)||($start&&$end&&$start>$end))throw new InvalidArgumentException('بازه دوره حقوقی معتبر نیست.');$data=[$title,$key,$year,$month,$start,$end];if($id)Database::execute('UPDATE payroll_periods SET title=?,period_key=?,year=?,month=?,start_date=?,end_date=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO payroll_periods(title,period_key,year,month,start_date,end_date,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?, ?,"draft",?,NOW(),NOW())',[...$data,(int)Auth::user()['id']]);Auth::log((int)Auth::user()['id'],$id?'payroll_period_updated':'payroll_period_created','payroll_periods',$id?:((int)Database::lastInsertId()));flash('دوره حقوقی ذخیره شد.');}}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Payroll period: '.$e->getMessage());flash('عملیات دوره حقوقی انجام نشد.','danger');}redirect('/admin/payroll-periods.php');}
$edit=isset($_GET['edit'])?Database::fetch('SELECT * FROM payroll_periods WHERE id=?',[(int)$_GET['edit']]):null;$periods=Database::fetchAll('SELECT p.*,(SELECT COUNT(*) FROM payroll_slips s WHERE s.period_id=p.id) slip_count FROM payroll_periods p ORDER BY p.year DESC,p.month DESC,p.id DESC');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>دوره‌های حقوق و دستمزد</h1><p>چرخه ایمپورت، انتشار و قفل دوره</p></div><a class="btn btn-primary" href="/admin/payroll-import.php">ایمپورت حقوق</a></div><nav class="workforce-tabs"><a class="is-active" href="/admin/payroll-periods.php">دوره‌ها</a><a href="/admin/payroll-fields.php">فیلدها</a><a href="/admin/payroll-import.php">ایمپورت</a><a href="/admin/payroll-slips.php">فیش‌ها</a></nav><div class="workforce-grid"><section class="card"><h2><?=$edit?'ویرایش دوره':'دوره جدید'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($edit['title']??'')?>" required></label><label class="form-field"><span>کلید دوره</span><input name="period_key" dir="ltr" value="<?=e($edit['period_key']??'')?>" placeholder="1405-01" required></label><div class="compact-grid"><label class="form-field"><span>سال</span><input type="number" name="year" value="<?=e($edit['year']??1405)?>"></label><label class="form-field"><span>ماه</span><input type="number" min="1" max="12" name="month" value="<?=e($edit['month']??1)?>"></label><label class="form-field"><span>شروع</span><?=app_date_input('start_date',$edit['start_date']??null)?></label><label class="form-field"><span>پایان</span><?=app_date_input('end_date',$edit['end_date']??null)?></label></div><div class="form-actions"><button class="btn btn-primary">ذخیره</button><?php if($edit):?><a class="btn" href="/admin/payroll-periods.php">انصراف</a><?php endif?></div></form></section><section class="card"><p>ترتیب امن عملیات:</p><ol><li>تعریف دوره</li><li>ایمپورت و بررسی</li><li>انتشار فیش‌ها</li><li>قفل دوره</li></ol><p class="muted">لغو و قفل، داده‌ها را حذف نمی‌کند.</p></section></div><section class="card"><div class="table-wrap"><table><thead><tr><th>دوره</th><th>کلید</th><th>فیش</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php $labels=['draft'=>'پیش‌نویس','imported'=>'ایمپورت‌شده','published'=>'منتشرشده','locked'=>'قفل‌شده','cancelled'=>'لغوشده'];foreach($periods as $p):?><tr><td><?=e($p['title'])?></td><td dir="ltr"><?=e($p['period_key'])?></td><td><?=$p['slip_count']?></td><td><span class="workforce-status status-<?=e($p['status'])?>"><?=e($labels[$p['status']]??'')?></span></td><td><div class="form-actions"><?php if(!in_array($p['status'],['locked','cancelled'],true)):?><a class="btn btn-small" href="?edit=<?=$p['id']?>">ویرایش</a><?php endif?><?php if($p['status']==='imported'&&PayrollRepository::canPublish()):?><form method="post" onsubmit="return confirm('همه فیش‌های آماده برای کاربران منتشر شوند؟')"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="publish"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-small btn-primary">انتشار</button></form><?php endif?><?php if($p['status']==='published'&&PayrollRepository::canPublish()):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="lock"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-small">قفل</button></form><?php endif?><?php if($p['status']==='locked'&&Auth::isSuperAdmin()):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="unlock"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-small">بازکردن قفل</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
